/**
 * Page-level rubric. Each check: id, cat (seo|aeo|geo), group (sub-area shown in the UI), name, weight,
 * tag (OBSERVED measured | INFERRED heuristic), test(p, s) -> {ratio 0..1 | null (not measurable), detail},
 * why, steps, platform (extra steps by detected platform), goal (used in the Claude prompt).
 * Add a check: one entry here, a fixture assertion in tests/e2e.mjs, and a guide link in lib/skills.js.
 */
const share = (arr, pred) => (arr.length ? arr.filter(pred).length / arr.length : null);
const LOCAL = /LocalBusiness|Store|Restaurant|Contractor|Plumber|Electrician|Roofing|HVAC|Dentist|AutoRepair|LegalService|ProfessionalService|HomeAndConstruction|MedicalBusiness|CleaningService/;
const ENTITY = /Organization|LocalBusiness|Corporation|ProfessionalService|Store|Restaurant|Contractor|Person|NGO|OnlineStore|OnlineBusiness/;
const types = (o) => [].concat(o?.["@type"] || []).map(String);
const ofType = (p, re) => p.jsonld.find((o) => types(o).some((t) => re.test(t)));
const entityOf = (p) => ofType(p, ENTITY);
const isLocal = (p) => types(entityOf(p) || {}).some((t) => LOCAL.test(t));
const isHome = (p) => p.path === "/" || p.path === "";
const skips = (levels) => { const seq = [1, ...levels]; return seq.slice(1).filter((b, i) => b - seq[i] > 1).length; };
const textHas = (p, s) => !!s && (p.renderedText + " " + p.title).toLowerCase().includes(String(s).toLowerCase());
const brand = (p) => entityOf(p)?.name || p.og.siteName || "";
const brandCore = (b) => b.replace(/[,.]?\s+(co|company|llc|inc|ltd|corp|corporation|group)\.?$/i, "").trim().toLowerCase();
const KG = /wikipedia\.org|wikidata\.org|linkedin\.com|crunchbase\.com|google\.[a-z.]+\/maps|maps\.google|goo\.gl\/maps|maps\.app\.goo\.gl|g\.page|share\.google|business\.google|maps\.apple|yelp\.com|bbb\.org/i;
const hostOf = (u) => { try { return new URL(u).hostname.replace(/^www\./, ""); } catch { return String(u); } };
const wordsOf = (s) => new Set((s || "").toLowerCase().match(/[a-z0-9]{3,}/g) || []);
const overlap = (a, b) => { const A = wordsOf(a), B = wordsOf(b); return A.size && B.size ? [...A].filter((w) => B.has(w)).length / Math.min(A.size, B.size) : 0; };
const n = (v, good, bad) => (v == null ? null : v <= good ? 1 : v >= bad ? 0 : 1 - (v - good) / (bad - good));
const yes = (b) => (b ? 1 : 0);

